<script setup>
import { computed, inject, nextTick, reactive, ref } from 'vue';
import { TYPE_KIND } from '../api/training.js';
import { Aperture, X, ArrowLeft, ArrowRight, Check, LockKeyhole, Globe, ShieldCheck, ChevronDown } from 'lucide-vue-next';
import UiButton from './UiButton.vue';
import UiBadge from './UiBadge.vue';
import UiDialog from './UiDialog.vue';
import detectionVisual from '../assets/project-types/detection.png';
import classificationVisual from '../assets/project-types/classification.png';
import instanceVisual from '../assets/project-types/instance.png';
import actionVisual from '../assets/project-types/action.png';
import keypointsVisual from '../assets/project-types/keypoints.png';
import multimodalVisual from '../assets/project-types/multimodal.png';
import semanticVisual from '../assets/project-types/semantic.png';
import collectionVisual from '../assets/project-types/collection.png';
import faceVisual from '../assets/project-types/face-recognition.png';
const props = defineProps({ submit: Function });
const emit = defineEmits(['cancel', 'done']);
// Which project types the backend can create today (GET kinds/): a type with no kind, or one not available yet, is shown and cannot be created.
const kinds = inject('kinds', ref([]));
const kindOf = name => kinds.value.find(k => k.key === TYPE_KIND[name]);
const available = computed(() => !!kindOf(form.task)?.available);
const busy = ref(false); const created = ref(null);
const step = ref(1); const expanded = ref(false); const errors = ref([]); const cancelDialog = ref(false);
const form = reactive({ name: '', purpose: '', visibility: 'Private', share: false, group: '', task: 'Instance Segmentation', classification: 'Single-label', training: 'Only this project’s own models', retention: 'Until I delete it', access: 'Only me', aws: false, local: false, deletion: false });
const tasks = [
  { name: 'Object Detection', image: detectionVisual, alt: 'Six cars individually enclosed by violet bounding boxes in an overhead parking-lot image.', description: 'Find objects and their positions with bounding boxes.', tags: ['Bounding boxes', 'Counts', 'Tracking'], example: 'Find and count cars in a parking lot.', output: 'One box and class label for each object.' },
  { name: 'Classification', image: classificationVisual, alt: 'A living-room photograph with one image-level Living room classification label.', description: 'Assign one or more labels to an entire image.', tags: ['Image labels', 'Filtering'], example: 'Sort room photos into kitchen, bedroom and living room.', output: 'An image-level label, or several labels in multi-label mode.' },
  { name: 'Instance Segmentation', image: instanceVisual, alt: 'A room with separate colored polygon masks and vertex points for two walls, a window and a door.', description: 'Identify individual objects and trace their actual shapes.', tags: ['Polygons', 'Measuring', 'Irregular shapes'], example: 'Outline each wall, window and door in a room.', output: 'A separate polygon or mask for each object.' },
  { name: 'Action Recognition', image: actionVisual, alt: 'A welder with a highlighted Welding time interval from 00:02 to 00:08.', description: 'Identify actions and when they happen in a video.', tags: ['Video actions', 'Temporal labels'], example: 'Identify when a worker starts and finishes welding.', output: 'An action label attached to a time interval.' },
  { name: 'Keypoint Detection', image: keypointsVisual, alt: 'An athlete with connected shoulder, elbow, wrist, hip, knee and ankle keypoints.', description: 'Mark important points and connect them into a skeleton.', tags: ['Skeletons', 'Pose estimation'], example: 'Locate a person’s shoulders, elbows and wrists.', output: 'Named points and connections for each subject.' },
  { name: 'Multimodal', image: multimodalVisual, alt: 'A room photograph paired with the question What is beside the sofa and answer A green plant.', description: 'Pair images with prompts, answers or descriptions.', tags: ['Prompts', 'Questions', 'Captions'], example: 'Describe a room’s layout or answer questions about it.', output: 'Image and text pairs for your chosen task.' },
  { name: 'Face Recognition', image: faceVisual, alt: 'Two synthetic portraits of the same fictional adult linked as a face match.', description: 'Match a face against enrolled reference images.', tags: ['Face matching', 'Identity verification'], example: 'Compare a new face image with an enrolled reference.', output: 'A match or no-match result against the reference identity. Coming soon.' },
  { name: 'Semantic Segmentation', image: semanticVisual, alt: 'A room with consistent class colors for walls, floor, window, ceiling and door, plus a legend.', description: 'Assign a class to each pixel in an image.', tags: ['Pixel labels', 'Scene understanding'], example: 'Separate all wall, floor and window regions.', output: 'A class map covering the image, without separate object identities.' },
  { name: 'Data Collection', image: collectionVisual, alt: 'Six room photographs organized as a labeled media contact sheet.', description: 'Organize media before choosing a labeling workflow.', tags: ['Collect', 'Organize'], example: 'Build an image library for a future project.', output: 'An organized collection of media and metadata.' },
];
const current = computed(() => tasks.find(t => t.name === form.task));
const visibilityDescription = computed(() => form.visibility === 'Public'
  ? 'Public listing: anyone could discover the project name, purpose and project type. Photos and annotations are not made public by this choice; access is configured separately in Data policy.'
  : 'Private listing: the project is hidden from public discovery. Only you and permitted project members could see its listing. Access to photos and annotations is configured separately in Data policy.');
const initial = JSON.stringify(form);
const dirty = computed(() => JSON.stringify(form) !== initial);
async function go(target) {
  errors.value = [];
  if (target > 1) {
    if (!form.name.trim()) errors.value.push('Enter a project name.');
    if (!form.purpose.trim()) errors.value.push('Describe what you want this project to do.');
    if (form.share && !form.group.trim()) errors.value.push('Enter an annotation group name.');
  }
  if (target > 2 && !form.deletion) errors.value.push('Confirm the deletion-on-request rule before continuing.');
  if (errors.value.length) { await nextTick(); document.getElementById('create-errors')?.focus(); return; }
  step.value = target; await nextTick(); document.getElementById('create-heading')?.focus(); window.scrollTo(0, 0);
}
function cancel() { if (dirty.value) cancelDialog.value = true; else emit('cancel'); }
async function create() {
  if (busy.value || !available.value) return;
  busy.value = true; errors.value = [];
  try { created.value = await props.submit({ ...form, name: form.name.trim(), purpose: form.purpose.trim(), group: form.group.trim() }); }
  catch (error) { errors.value = [error.message]; await nextTick(); document.getElementById('create-errors')?.focus(); }
  finally { busy.value = false; }
}
</script>
<template>
  <div class="create-page">
    <header class="create-header"><a href="#projects" @click.prevent="cancel"><Aperture :size="25" /><strong>Vision workspace</strong></a><button class="icon-button" aria-label="Close project creation" @click="cancel"><X :size="20" /></button></header>
    <main class="create-main">
      <div class="create-intro"><div class="eyebrow">MY WORKSPACE / NEW PROJECT</div><h1 id="create-heading" tabindex="-1">{{ ['Let’s create your project.', 'Your data. Your choices.', 'Review your project.'][step - 1] }}</h1><p>{{ ['Choose what you want to build and how your data will be labeled.', 'Set the permissions and handling rules for this project’s data.', 'Check your choices before creating the project.'][step - 1] }}</p></div>
      <nav class="create-steps" aria-label="Project creation steps"><button v-for="(label, index) in ['Project details', 'Data policy', 'Review & create']" :key="label" :class="{current: step === index + 1, done: step > index + 1}" :aria-current="step === index + 1 ? 'step' : undefined" @click="go(index + 1)"><span><Check v-if="step > index + 1" :size="14" /><template v-else>{{ index + 1 }}</template></span>{{ label }}</button></nav>
      <div class="prototype-banner"><UiBadge tone="purple">Coming soon</UiBadge><span>Listing visibility, shared annotation definitions and classification mode are not saved yet. Everything else is saved with the project.</span></div>
      <div v-if="errors.length" id="create-errors" class="create-errors" role="alert" tabindex="-1"><strong>Check these details</strong><ul><li v-for="error in errors" :key="error">{{ error }}</li></ul></div>
      <form v-if="step === 1" id="project-details" @submit.prevent="go(2)">
        <div class="project-details-grid"><div><label class="field-label" for="new-project-name">Project name <span>*</span></label><input id="new-project-name" v-model="form.name" class="text-input" maxlength="80" placeholder="e.g. Room Wall Segmentation"><label class="field-label" for="project-purpose">What will you use this project for? <span>*</span></label><textarea id="project-purpose" v-model="form.purpose" class="text-input" rows="2" maxlength="500" placeholder="e.g. Detect room walls and windows to preview paint colors."></textarea></div><fieldset><legend>Project listing visibility</legend><div class="choice-buttons"><label :class="{chosen: form.visibility === 'Private'}"><input v-model="form.visibility" name="visibility" type="radio" value="Private"><LockKeyhole :size="15" /> Private</label><label :class="{chosen: form.visibility === 'Public'}"><input v-model="form.visibility" name="visibility" type="radio" value="Public"><Globe :size="15" /> Public</label></div><p class="field-help visibility-description" aria-live="polite">{{ visibilityDescription }}</p><label class="check-line"><input v-model="form.share" type="checkbox"> Share annotation definitions between projects</label><label v-if="form.share" class="field-label" for="annotation-group">Annotation group name<input id="annotation-group" v-model="form.group" class="text-input" placeholder="e.g. Interior surfaces" maxlength="80"></label></fieldset></div>
        <div class="type-heading"><h2>Project type</h2><span>Select a task to see its example and expected output.</span></div>
        <div class="task-layout"><div><div class="task-options" role="radiogroup" aria-label="Project type"><label v-for="task in tasks.slice(0, expanded ? tasks.length : 7)" :key="task.name" :class="['task-option', {chosen: form.task === task.name}]"><input v-model="form.task" name="task" type="radio" :value="task.name"><div><div class="task-name"><strong>{{ task.name }}</strong><span class="task-tags"><span v-for="tag in task.tags" :key="tag">{{ tag }}</span></span></div><p>{{ task.description }}</p></div></label></div><UiButton class="expand-tasks" @click="expanded = !expanded">{{ expanded ? 'Show fewer project types' : 'Show more project types' }}<ChevronDown :size="15" /></UiButton><fieldset v-if="form.task === 'Classification'" class="classification-options"><legend>Classification mode</legend><label><input v-model="form.classification" name="classification" type="radio" value="Single-label"> Single-label</label><label><input v-model="form.classification" name="classification" type="radio" value="Multi-label"> Multi-label</label></fieldset></div>
          <aside class="task-example"><div class="example-art"><img :key="form.task" :src="current.image" :alt="current.alt" width="1536" height="1024" decoding="async"><span class="illustration-caption">AI-generated example · No inference is running</span></div><div class="example-content"><UiBadge tone="purple">{{ form.task }}</UiBadge> <UiBadge v-if="kinds.length && !available">Coming soon</UiBadge><h2>{{ current.example }}</h2><p>{{ current.output }}</p><div class="example-note"><ShieldCheck :size="19" /><span>Choose the output your project needs. You can explore every task in this frontend prototype.</span></div></div></aside></div>
      </form>
      <div v-else-if="step === 2" class="policy-layout"><div class="policy-questions">
        <fieldset class="policy-card"><legend><span>1</span> May this data be used to train models?</legend><label v-for="(choice, index) in ['No', 'Only this project’s own models', 'Also AADML’s shared models']" :key="choice" class="policy-option"><input v-model="form.training" name="training" type="radio" :value="choice"><div><strong>{{ choice }}</strong><p>{{ ['No labeling assignment, dataset version or training run can be made from it.', 'A person must start each step; nothing is trained automatically.', 'Data may also improve models outside this project.'][index] }}</p></div></label></fieldset>
        <fieldset class="policy-card"><legend><span>2</span> How long may AADML keep the data?</legend><div class="retention-options"><label v-for="choice in ['30 days', '90 days', '180 days', '365 days', '730 days', 'Until I delete it']" :key="choice"><input v-model="form.retention" name="retention" type="radio" :value="choice">{{ choice }}</label></div><p>{{ form.retention === 'Until I delete it' ? 'Nothing is deleted automatically under this choice.' : 'The intended rule removes records older than the selected period with their files. This cannot be undone.' }}</p></fieldset>
        <fieldset class="policy-card"><legend><span>3</span> Who may see the data?</legend><label v-for="(choice, index) in ['Only me', 'People I invite to the project', 'Also an outside labeling vendor']" :key="choice" class="policy-option"><input v-model="form.access" name="access" type="radio" :value="choice"><div><strong>{{ choice }}</strong><p>{{ ['Nobody else can be given a role; existing roles would stop working.', 'Invited members can only do what their assigned roles allow.', 'A photo assignment may be given to a labeling company you choose.'][index] }}</p></div></label></fieldset>
        <fieldset class="policy-card"><legend><span>4</span> Where may the data be stored and processed?</legend><label class="policy-option"><input type="checkbox" checked disabled><div><strong>AADML’s servers</strong><p>Required in the existing workflow: this is where the data arrives.</p></div></label><label class="policy-option"><input v-model="form.aws" type="checkbox"><div><strong>Also AADML’s AWS</strong><p>Allow GPU training in AADML’s AWS account.</p></div></label><label class="policy-option"><input v-model="form.local" type="checkbox" disabled><div><strong>Also my own machine for training</strong> <UiBadge>Coming soon</UiBadge><p>Allow data to be sent to a machine you connect yourself.</p></div></label></fieldset>
        <fieldset class="policy-card"><legend><span>5</span> Deletion on request</legend><p>When a person asks for a photo to be deleted: it is removed within 30 days, left out of every future training, and the models trained on it are listed for you.</p><label class="check-line"><input v-model="form.deletion" type="checkbox"> I confirm this rule</label></fieldset>
      </div><aside class="policy-summary"><ShieldCheck :size="30" /><h2>Set clear boundaries.</h2><p>These choices follow your existing data-policy questionnaire. Review them before adding images.</p><hr><strong>{{ form.name }}</strong><p>{{ form.task }}</p><p class="field-help">These answers are saved with the project. They decide who may see and use its data; its Owner can change them later.</p></aside></div>
      <section v-else-if="created" class="review-layout"><div class="panel" role="status"><div class="review-heading"><h2><Check :size="18" /> {{ created.name }} is created</h2></div><p class="field-help">Its data-use answers are saved. Next, bring in its photos: upload them here, or connect the app that sends them.</p><div class="dialog-actions"><UiButton @click="emit('done', 'projects', created)">Back to projects</UiButton><UiButton @click="emit('done', 'connect', created)">Connect an app</UiButton><UiButton variant="primary" @click="emit('done', 'upload', created)">Upload photos</UiButton></div></div></section>
      <section v-else class="review-layout"><div class="panel"><div class="review-heading"><h2>Project details</h2><UiButton @click="go(1)">Edit details</UiButton></div><dl><dt>Name</dt><dd>{{ form.name }}</dd><dt>Purpose</dt><dd>{{ form.purpose }}</dd><dt>Project type</dt><dd>{{ form.task }}<span v-if="form.task === 'Classification'"> · {{ form.classification }}</span></dd><dt>Listing visibility</dt><dd>{{ form.visibility }}</dd><dt>Annotation group</dt><dd>{{ form.share ? form.group : 'Separate definitions for this project' }}</dd></dl></div><div class="panel"><div class="review-heading"><h2>Data policy</h2><UiButton @click="go(2)">Edit policy</UiButton></div><dl><dt>Training use</dt><dd>{{ form.training }}</dd><dt>Retention</dt><dd>{{ form.retention }}</dd><dt>Photo access</dt><dd>{{ form.access }}</dd><dt>Storage & processing</dt><dd>AADML’s servers{{ form.aws ? ', AADML’s AWS' : '' }}{{ form.local ? ', my own machine' : '' }}</dd><dt>Deletion on request</dt><dd><Check :size="14" /> Confirmed</dd></dl></div><div class="review-disclaimer"><strong>{{ available ? 'Ready to create' : 'Coming soon' }}</strong><p>{{ available ? 'Create makes the project in your current workspace and saves its data-use answers.' : 'This project type cannot be created yet. Choose Instance Segmentation or Data Collection.' }}</p></div></section>
    </main>
    <footer class="create-footer"><UiButton @click="cancel">Cancel</UiButton><span>Step {{ step }} of 3</span><div><UiButton v-if="step > 1 && !created" @click="go(step - 1)"><ArrowLeft :size="16" /> Back</UiButton><UiButton v-if="step < 3" variant="primary" @click="go(step + 1)">{{ step === 1 ? 'Continue to data policy' : 'Review project' }}<ArrowRight :size="16" /></UiButton><UiButton v-else-if="!created" variant="primary" :disabled="busy || !available" @click="create"><Check :size="16" /> {{ busy ? 'Creating…' : 'Create project' }}</UiButton></div></footer>
    <UiDialog :open="cancelDialog" title="Discard project draft?" @close="cancelDialog = false"><p class="dialog-description">Your project details and policy selections have not been saved. You can continue editing or discard this draft.</p><div class="dialog-actions"><UiButton @click="cancelDialog = false">Keep editing</UiButton><UiButton variant="primary" @click="emit('cancel')">Discard draft</UiButton></div></UiDialog>
  </div>
</template>
